 1	import java.util.OptionalInt;
 2	
 3	final class BinarySearch {
 4	    private static final int NOT_FOUND = -1;
 5	
 6	    private BinarySearch() {
 7	    }
 8	
 9	    static int binarySearch(int[] arr, int target) {
10	        return findIndex(arr, target).orElse(NOT_FOUND);
11	    }
12	
13	    private static OptionalInt findIndex(int[] arr, int target) {
14	        if (arr.length == 0) {
15	            return OptionalInt.empty();
16	        }
17	
18	        return findIndex(arr, target, 0, arr.length - 1);
19	    }
20	
21	    private static OptionalInt findIndex(int[] arr, int target, int low, int high) {
22	
23	        while (low <= high) {
24	            int middleIndex = low + (high - low) / 2;
25	            int middleValue = arr[middleIndex];
26	
27	            if (middleValue == target) {
28	                return OptionalInt.of(middleIndex);
29	            }
30	
31	            if (middleValue < target) {
32	                low = middleIndex + 1;
33	            } else {
34	                high = middleIndex - 1;
35	            }
36	        }
37	
38	        return OptionalInt.empty();
39	    }
40	
41	    private static String formatSearchResult(int result) {
42	        return result == NOT_FOUND
43	                ? "Element is not present in array"
44	                : "Element is present at index " + result;
45	    }
46	
47	    public static void main(String[] args) {
48	        int[] arr = { 2, 3, 4, 10, 40 };
49	        int target = 10;
50	        int result = binarySearch(arr, target);
51	
